import type { ModelFixtures } from './modelFixtures'
/** Default numeric IDs are generated by Payload; align test-only sequences with tracked fixtures. */
export async function collidingRewards(fixtures: ModelFixtures, name: string) {
  const data = () => ({ name, slug: fixtures.name() })
  let custom = await fixtures.create('resources', data())
  let ordinary = await fixtures.create('ordinary-items', data())
  for (let index = 0; custom.id !== ordinary.id; index++) {
    if (index >= 10000)
      throw new Error('Test ID sequences are too far apart to prepare collision fixtures.')
    if (custom.id < ordinary.id) custom = await fixtures.create('resources', data())
    else ordinary = await fixtures.create('ordinary-items', data())
  }
  return { custom, ordinary }
}
